#!/bin/sh
# Builds addons/purble-place-bundle.js: the whole Purble Place game as one plain script.
# The OS loads the game's real files when it can, but Chrome won't load JavaScript modules
# from a page opened as a file (file://), so it falls back to this copy there.
# Run it from the repo root after changing anything in purble-place/src:
#   sh addons/build-purble-bundle.sh
set -e
npx --yes esbuild@0.28.2 purble-place/src/index.js \
  --bundle --format=iife --global-name=PurblePlaceBundle \
  --define:import.meta.url=__PURBLE_PLACE_URL__ \
  --banner:js="/* Generated by addons/build-purble-bundle.sh from purble-place/src. Don't edit by hand. */
var __PURBLE_PLACE_URL__ = new URL('../purble-place/src/shell/shell.js', document.currentScript.src).href;" \
  --outfile=addons/purble-place-bundle.js
